export type GetOrganogramQueryResult = NonNullable<
  Awaited<ReturnType<typeof getOrganogram>>
>
export type GetOrganogramQueryError =
  GetOrganogram400 | GetOrganogram401 | GetOrganogram403 | GetOrganogram500

/**
 * @summary Buscar o organograma completo da equipe
 */
export const useGetOrganogram = <
  TError =
    GetOrganogram400 | GetOrganogram401 | GetOrganogram403 | GetOrganogram500,
>(options?: {
  swr?: SWRConfiguration<Awaited<ReturnType<typeof getOrganogram>>, TError> & {
    swrKey?: Key
    enabled?: boolean
  }
  request?: SecondParameter<typeof customFetch>
}) => {
  const { swr: swrOptions, request: requestOptions } = options ?? {}

  const isEnabled = swrOptions?.enabled !== false
  const swrKey =
    swrOptions?.swrKey ?? (() => (isEnabled ? getGetOrganogramKey() : null))
  const swrFn = () => getOrganogram(requestOptions)

  const query = useSwr<Awaited<ReturnType<typeof swrFn>>, TError>(
    swrKey,
    swrFn,
    swrOptions,
  )

  return {
    swrKey,
    ...query,
  }
}
/**
 * Este endpoint retorna a lista de membros da equipe que o usuário logado pode gerenciar.

* **Segurança**: Protegido por autenticação JWT (token de sessão) e CSRF via cookie/header.
* **Autorização**:
  - Admin/Dev: Vê todos os usuários com posição em time
  - Diretor: Vê todos os usuários com posição em time
  - Supervisor: Vê apenas subordinados da própria equipe
* **Validação de conta**: Verifica se a conta do usuário autenticado está ativa.

**Dados retornados**:
- ID, nome, email e posição de cada membro
- Status da exceção de prazo (bookingExceptionUntil)

**Uso principal**: Tela de "Liberar Regras de Reserva"

**Middlewares aplicados**:
- `verifyJWT`: Valida o token JWT e extrai os dados do usuário autenticado
- `validateUserAccount`: Verifica se a conta do usuário autenticado está ativa
 * @summary Listar membros da equipe para gestão
 */
export type getTeamMembersResponse200 = {
  data: GetTeamMembers200
  status: 200
}

export type getTeamMembersResponse400 = {
  data: GetTeamMembers400
  status: 400
}

export type getTeamMembersResponse401 = {
  data: GetTeamMembers401
  status: 401
}

export type getTeamMembersResponse403 = {
  data: GetTeamMembers403
  status: 403
}

export type getTeamMembersResponse404 = {
  data: GetTeamMembers404
  status: 404
}

export type getTeamMembersResponse500 = {
  data: GetTeamMembers500
  status: 500
}

export type getTeamMembersResponseSuccess = getTeamMembersResponse200 & {
  headers: Headers
}
export type getTeamMembersResponseError = (
  | getTeamMembersResponse400
  | getTeamMembersResponse401
  | getTeamMembersResponse403
  | getTeamMembersResponse404
  | getTeamMembersResponse500
) & {
  headers: Headers
}

export const getGetTeamMembersUrl = () => {
  return `${process.env.NEXT_PUBLIC_API_URL}/v1/private/team/members`
}

export const getTeamMembers = async (
  options?: RequestInit,
): Promise<getTeamMembersResponseSuccess> => {
  return customFetch<getTeamMembersResponseSuccess>(getGetTeamMembersUrl(), {
    ...options,
    method: 'GET',
  })
}

export const getGetTeamMembersKey = () =>
  [`${process.env.NEXT_PUBLIC_API_URL}/v1/private/team/members`] as const

export type GetTeamMembersQueryResult = NonNullable<
  Awaited<ReturnType<typeof getTeamMembers>>
>
export type GetTeamMembersQueryError =
  | GetTeamMembers400
  | GetTeamMembers401
  | GetTeamMembers403
  | GetTeamMembers404
  | GetTeamMembers500

/**
 * @summary Listar membros da equipe para gestão
 */
export const useGetTeamMembers = <
  TError =
    | GetTeamMembers400
    | GetTeamMembers401
    | GetTeamMembers403
    | GetTeamMembers404
    | GetTeamMembers500,
>(options?: {
  swr?: SWRConfiguration<Awaited<ReturnType<typeof getTeamMembers>>, TError> & {
    swrKey?: Key
    enabled?: boolean
  }
  request?: SecondParameter<typeof customFetch>
}) => {
  const { swr: swrOptions, request: requestOptions } = options ?? {}

  const isEnabled = swrOptions?.enabled !== false
  const swrKey =
    swrOptions?.swrKey ?? (() => (isEnabled ? getGetTeamMembersKey() : null))
  const swrFn = () => getTeamMembers(requestOptions)

  const query = useSwr<Awaited<ReturnType<typeof swrFn>>, TError>(
    swrKey,
    swrFn,
    swrOptions,
  )

  return {
    swrKey,
    ...query,
  }
}
